def extract_symmetric(test_list):
    """Write a function to extract all the pairs which are symmetric in the given tuple list."""
    pairs = list(test_list)
    lookup = set(pairs)
    symmetric = set()
    for a, b in pairs:
        if (b, a) in lookup:
            symmetric.add((a, b) if a <= b else (b, a))
    return symmetric
